3class Board {
4
5    String board[] = { " ", " ", " ", " ", " ", " ", " ", " ", " " };
6
7    void printBoard() {
8
9        System.out.println(" " + board[0] + " | " + board[1] + " | " + board[2]);
10        System.out.println("-----------");
11        System.out.println(" " + board[3] + " | " + board[4] + " | " + board[5]);
12        System.out.println("-----------");
13        System.out.println(" " + board[6] + " | " + board[7] + " | " + board[8]);
14
15    }
16
17
18    boolean updateBoard(int position, String type) {
19
20        // if a player selects position n, n-1 index should be updated
21        // if the position is not already filled, update the board
22        if (board[position - 1] == " ") {
23            board[position - 1] = type;
24            return true;
25        }
26
27        // if the position is already filled, ask user to select another position
28        else {
29            System.out.println("Position already selected. Select another position.");
30            return false;
31
32        }
33    }
34
35}
