57class Game {
58
59    Board board = new Board();
60    Player player1 = new Player("X");
61    Player player2 = new Player("O");
62
63    Player currentPlayer = player1;
64
65
66    void play() {
67        // using an infinite loop to run the game
68        // we will later add conditions to terminate the loop
69        String message = "enter the position (1 - 9):";
70        while (true) {
71
72            message = "enter the position (1 - 9):";
73            System.out.println(currentPlayer.name + " " + message);
74            Scanner input = new Scanner(System.in);
75            int position = input.nextInt();
76
77            // the updateBoard() method return true if
78            // the user selected position is not already filled
79            if (board.updateBoard(position, currentPlayer.type)) {
80
81                board.printBoard();
82
83                // changing current player when board is updated
84                if (currentPlayer == player1) {
85                    currentPlayer = player2;
86                }
87
88                else {
89                    currentPlayer = player1;
90
91                }
92
93            }
94
95        }
96
97    }
98
99
100}
